from pydantic import BaseModel, Field, constr

class SKUCode(str):
    @classmethod
    def __get_validators__(cls):
        yield cls.validate

    @classmethod
    def validate(cls, v):
        if not isinstance(v, str) or not v.match(r"^[A-Z]{3}-\d{4}$"):
            raise ValueError("Code must match ^[A-Z]{3}-\d{4}$")
        return v

class SKU(BaseModel):
    code: SKUCode = Field(..., alias="code")

def make_sku(code: str):
    return SKU(code=code)
